-- =============================================================================
-- PHASE 16: ASSET MASTER PRICE CATALOG (OCT 2026) & BRANCH PHYSICAL INVENTORY
-- =============================================================================
-- 1. Creates public.asset_catalog_items, public.branch_asset_inventory,
--    and public.asset_stock_movements.
-- 2. Seeds all October 2026 Master Price List SKUs with Cash & Carry,
--    Easy Buy 60D/12W/3M (1.12x), and Easy Buy 120D/24W/6M (1.21x) pricing.
-- 3. Seeds Ogijo Branch's exact 242 inventory rows (127 in-stock SKUs / 205 units).
-- =============================================================================

CREATE TABLE IF NOT EXISTS public.asset_catalog_items (
    item_id UUID PRIMARY KEY,
    sku_code TEXT NOT NULL UNIQUE,
    category TEXT NOT NULL,
    item_name TEXT NOT NULL UNIQUE,
    cash_and_carry_price NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    easy_buy_60d_price NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    easy_buy_120d_price NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    is_custom_price_allowed BOOLEAN NOT NULL DEFAULT FALSE,
    in_master_pdf BOOLEAN NOT NULL DEFAULT TRUE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_asset_catalog_category ON public.asset_catalog_items(category);
CREATE INDEX IF NOT EXISTS idx_asset_catalog_active ON public.asset_catalog_items(is_active);

CREATE TABLE IF NOT EXISTS public.branch_asset_inventory (
    inventory_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    branch_id UUID NOT NULL REFERENCES public.branches(branch_id) ON DELETE CASCADE,
    item_id UUID NOT NULL REFERENCES public.asset_catalog_items(item_id) ON DELETE CASCADE,
    quantity_on_hand INTEGER NOT NULL DEFAULT 0 CHECK (quantity_on_hand >= 0),
    quantity_reserved INTEGER NOT NULL DEFAULT 0 CHECK (quantity_reserved >= 0 AND quantity_reserved <= quantity_on_hand),
    reorder_level INTEGER NOT NULL DEFAULT 0,
    branch_item_alias TEXT,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    UNIQUE (branch_id, item_id)
);

CREATE INDEX IF NOT EXISTS idx_branch_asset_inventory_branch ON public.branch_asset_inventory(branch_id);
CREATE INDEX IF NOT EXISTS idx_branch_asset_inventory_item ON public.branch_asset_inventory(item_id);

CREATE TABLE IF NOT EXISTS public.asset_stock_movements (
    movement_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    branch_id UUID NOT NULL REFERENCES public.branches(branch_id) ON DELETE CASCADE,
    item_id UUID NOT NULL REFERENCES public.asset_catalog_items(item_id) ON DELETE CASCADE,
    loan_id UUID REFERENCES public.loans(loan_id) ON DELETE SET NULL,
    movement_type TEXT NOT NULL CHECK (
        movement_type IN ('INITIAL_SEED', 'RESTOCK', 'RESERVE_ON_APPLY', 'DEDUCT_ON_DISBURSE', 'RELEASE_ON_REJECT', 'ADJUSTMENT')
    ),
    quantity_delta INTEGER NOT NULL,
    reserved_delta INTEGER NOT NULL DEFAULT 0,
    balance_after INTEGER NOT NULL DEFAULT 0,
    unit_cash_price NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    performed_by TEXT,
    remarks TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_asset_stock_movements_branch ON public.asset_stock_movements(branch_id);
CREATE INDEX IF NOT EXISTS idx_asset_stock_movements_loan ON public.asset_stock_movements(loan_id);

-- Security Hardening: Enable RLS and restrict access to service_role only (matching ICARE baseline)
ALTER TABLE public.asset_catalog_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.branch_asset_inventory ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.asset_stock_movements ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.asset_catalog_items FROM anon, authenticated;
REVOKE ALL ON TABLE public.branch_asset_inventory FROM anon, authenticated;
REVOKE ALL ON TABLE public.asset_stock_movements FROM anon, authenticated;

GRANT ALL ON TABLE public.asset_catalog_items TO service_role;
GRANT ALL ON TABLE public.branch_asset_inventory TO service_role;
GRANT ALL ON TABLE public.asset_stock_movements TO service_role;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'asset_catalog_items' AND policyname = 'service_role_all_asset_catalog_items') THEN
        CREATE POLICY service_role_all_asset_catalog_items ON public.asset_catalog_items FOR ALL TO service_role USING (true) WITH CHECK (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'branch_asset_inventory' AND policyname = 'service_role_all_branch_asset_inventory') THEN
        CREATE POLICY service_role_all_branch_asset_inventory ON public.branch_asset_inventory FOR ALL TO service_role USING (true) WITH CHECK (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'asset_stock_movements' AND policyname = 'service_role_all_asset_stock_movements') THEN
        CREATE POLICY service_role_all_asset_stock_movements ON public.asset_stock_movements FOR ALL TO service_role USING (true) WITH CHECK (true);
    END IF;
END $$;

-- Seed Master Asset Catalog Items
ON CONFLICT (sku_code) DO UPDATE SET
    category = EXCLUDED.category,
    item_name = EXCLUDED.item_name,
    cash_and_carry_price = CASE WHEN public.asset_catalog_items.cash_and_carry_price = 0 THEN EXCLUDED.cash_and_carry_price ELSE public.asset_catalog_items.cash_and_carry_price END,
    easy_buy_60d_price = CASE WHEN public.asset_catalog_items.easy_buy_60d_price = 0 THEN EXCLUDED.easy_buy_60d_price ELSE public.asset_catalog_items.easy_buy_60d_price END,
    easy_buy_120d_price = CASE WHEN public.asset_catalog_items.easy_buy_120d_price = 0 THEN EXCLUDED.easy_buy_120d_price ELSE public.asset_catalog_items.easy_buy_120d_price END,
    in_master_pdf = EXCLUDED.in_master_pdf;

-- Seed Ogijo Branch Physical Inventory (242 rows / 205 physical units) if Ogijo branch exists and inventory is empty
DO $$
DECLARE
    v_ogijo_branch_id UUID;
    v_existing_count INTEGER;
BEGIN
    SELECT branch_id INTO v_ogijo_branch_id FROM public.branches WHERE LOWER(name) LIKE '%ogijo%' LIMIT 1;
    IF v_ogijo_branch_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_existing_count FROM public.branch_asset_inventory WHERE branch_id = v_ogijo_branch_id;
        IF v_existing_count = 0 THEN
            ON CONFLICT (branch_id, item_id) DO NOTHING;

            SELECT branch_id, item_id, 'INITIAL_SEED', quantity_on_hand, quantity_on_hand, 0.00, 'SYSTEM', 'Initial seed from OCTOBER_OGIJO_2026.xlsx'
            FROM public.branch_asset_inventory
            WHERE branch_id = v_ogijo_branch_id AND quantity_on_hand > 0;
        END IF;
    END IF;
END $$;